// Validate Binary Search Tree using sorted inorder verification
let tree = AnimatedBinaryTree<Int>()
tree.insert(10)
tree.insert(5)
tree.insert(15)

func isValidBST(t: AnimatedBinaryTree<Int>, keys: [Int]) -> Bool {
    var prev = Int.min
    for val in keys {
        if t.search(val) {
            if val <= prev {
                return false
            }
            prev = val
        }
    }
    return true
}

let keysToVerify = [5, 10, 15]
let isValid = isValidBST(t: tree, keys: keysToVerify)
